static void dfs(int *nums, int n, int start, int *cur, int depth, int **res, int *size, int **cols) {
  res[*size] = (int *)malloc(sizeof(int) * depth);
  for (int i = 0; i < depth; i++) res[*size][i] = cur[i];
  (*cols)[*size] = depth;
  (*size)++;
  for (int i = start; i < n; i++) {
    cur[depth] = nums[i];
    dfs(nums, n, i + 1, cur, depth + 1, res, size, cols);
  }
}

int **subsets(int *nums, int numsSize, int *returnSize, int **returnColumnSizes) {
  int **res = (int **)malloc(sizeof(int *) * 100000);
  *returnColumnSizes = (int *)malloc(sizeof(int) * 100000);
  int *cur = (int *)malloc(sizeof(int) * (numsSize + 1));
  *returnSize = 0;
  dfs(nums, numsSize, 0, cur, 0, res, returnSize, returnColumnSizes);
  free(cur);
  return res;
}

class Solution {
  void dfs(vector<int> &nums, int start, vector<int> &cur, vector<vector<int>> &res) {
    res.push_back(cur);
    for (int i = start; i < (int)nums.size(); i++) {
      cur.push_back(nums[i]);
      dfs(nums, i + 1, cur, res);
      cur.pop_back();
    }
  }

public:
  vector<vector<int>> subsets(vector<int> &nums) {
    vector<vector<int>> res;
    vector<int> cur;
    dfs(nums, 0, cur, res);
    return res;
  }
};

func subsets(nums []int) [][]int {
	var res [][]int
	var cur []int
	var dfs func(start int)
	dfs = func(start int) {
		tmp := make([]int, len(cur))
		copy(tmp, cur)
		res = append(res, tmp)
		for i := start; i < len(nums); i++ {
			cur = append(cur, nums[i])
			dfs(i + 1)
			cur = cur[:len(cur)-1]
		}
	}
	dfs(0)
	return res
}

class Solution {
  private void dfs(int[] nums, int start, List<Integer> cur, List<List<Integer>> res) {
    res.add(new ArrayList<>(cur));
    for (int i = start; i < nums.length; i++) {
      cur.add(nums[i]);
      dfs(nums, i + 1, cur, res);
      cur.remove(cur.size() - 1);
    }
  }

  public List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    dfs(nums, 0, new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        res = []
        cur = []

        def dfs(start: int):
            res.append(cur[:])
            for i in range(start, len(nums)):
                cur.append(nums[i])
                dfs(i + 1)
                cur.pop()

        dfs(0)
        return res

impl Solution {
  pub fn subsets(nums: Vec<i32>) -> Vec<Vec<i32>> {
    fn dfs(nums: &[i32], start: usize, cur: &mut Vec<i32>, res: &mut Vec<Vec<i32>>) {
      res.push(cur.clone());
      for i in start..nums.len() {
        cur.push(nums[i]);
        dfs(nums, i + 1, cur, res);
        cur.pop();
      }
    }
    let mut res = vec![];
    let mut cur = vec![];
    dfs(&nums, 0, &mut cur, &mut res);
    res
  }
}

const subsets = (nums: number[]): number[][] => {
  const res: number[][] = [];
  const cur: number[] = [];
  const dfs = (start: number) => {
    res.push([...cur]);
    for (let i = start; i < nums.length; i++) {
      cur.push(nums[i]);
      dfs(i + 1);
      cur.pop();
    }
  };
  dfs(0);
  return res;
};
